// Model helpers for the Transformation Rule builder.
//
// A rule reads one value, pipes it through an ordered list of actions, and
// writes the result back. A `document`-scoped rule ("routing") instead stamps a
// document attribute — today only the sub-organisation.
//
// This module holds:
//   • ACTION_CATALOGUE — every action, its params spec and defaults
//   • applyAction / chainValues — the client-side preview engine
//   • assembleApiCore / fromApiRule — builder form ↔ API payload
//   • ruleSentence — the plain-English summary shown in the list and builder
//
// The `applies_when` condition tree is IDENTICAL to the custom-validation
// rules', so its builder shapes, serializer, parser, field loaders and the
// ConditionGroup component are all reused from ../CustomValidationRules
// rather than duplicated here.

import type {
  TransformationRule,
  TransformationRuleScope,
  TransformationRuleSourceBadge,
  TransformationAction,
  UpdateTransformationRulePayload,
} from 'src/services/settings/TransformationRulesApiService';
import {
  newGroup,
  isAppliesWhenEmpty,
  slugify,
  buildAppliesWhenFromGroup,
  groupFromAppliesWhen,
  isBuilderGroup,
  type BuilderGroup,
  type BuilderCondition,
  type FieldOption,
} from '../CustomValidationRules/rule-builder-model';

export type { FieldOption };
export { slugify };

// ---- Action catalogue ----------------------------------------------------

/** How a param is edited. `select` renders a dropdown, the rest map to inputs. */
type ParamType = 'select' | 'text' | 'number' | 'toggle';

export interface ParamSpec {
  /** Key inside the action's `params` object. */
  k: string;
  /** i18n key for the field label. */
  labelKey: string;
  type: ParamType;
  /** `select` only: the stored values, and the labels shown for them. */
  opts?: string[];
  /** i18n keys for the option labels; falls back to the raw value. */
  optLabelKeys?: string[];
  /** Literal option labels (used where the value IS the label, e.g. patterns). */
  optLabels?: string[];
  min?: number;
  maxlen?: number;
  /** i18n key for the placeholder. */
  phKey?: string;
  /** Span the full width of the param grid. */
  wide?: boolean;
  /** Changing this param changes which OTHER params are shown. */
  struct?: boolean;
}

export interface ActionMeta {
  /** i18n key for the verb shown in the step head ("Change case", "Trim", …). */
  verbKey: string;
  /** Short monospace glyph shown in the add-step menu. */
  icon: string;
  /** i18n key for the one-line hint in the add-step menu. */
  hintKey: string;
  /** i18n key for the menu section this action belongs to. */
  groupKey: string;
  /** Static param list, or 'dynamic' when the spec depends on current values. */
  params: ParamSpec[] | 'dynamic';
  /** Default params for a freshly added step. */
  def: Record<string, unknown>;
  /** Offered on routing (document-scope) rules. */
  doc?: boolean;
  /** ONLY valid on routing rules (hidden for header/column). */
  docOnly?: boolean;
}

