// The shared field-option builders speak the validation-rule scope vocabulary
// ('header' | 'line' | 'table'); a transformation rule speaks
// 'header' | 'column' | 'document'. Only one distinction actually matters to
// them — whether row.* table columns are in play — so translate here, once,
// rather than inline at each call site.
export function sharedFieldScope(scope: TransformationRuleScope): 'header' | 'line' {
  return scope === 'column' ? 'line' : 'header';
}

export function actionMeta(type: string): ActionMeta | undefined {
  return ACTION_CATALOGUE[type];
}

/** Fresh default params for a newly added step (deep-copied so steps never
 *  share a params object). */
export function defaultParams(type: string): Record<string, unknown> {
  const meta = ACTION_CATALOGUE[type];
  return meta ? (JSON.parse(JSON.stringify(meta.def)) as Record<string, unknown>) : {};
}

export function newAction(type: string): TransformationAction {
  return { type, params: defaultParams(type) };
}

/** The action types offered for a scope, grouped for the add-step menu.
 *  Routing rules only get actions flagged `doc`; field rules exclude `docOnly`. */
export function actionsForScope(
  scope: TransformationRuleScope,
): { groupKey: string; types: string[] }[] {
  const isDoc = scope === 'document';
  return ACTION_GROUP_KEYS.map((groupKey) => ({
    groupKey,
    types: Object.keys(ACTION_CATALOGUE).filter((type) => {
      const meta = ACTION_CATALOGUE[type];
      if (meta.groupKey !== groupKey) return false;
      return isDoc ? !!meta.doc : !meta.docOnly;
    }),
  })).filter((g) => g.types.length > 0);
}

/** The param spec for one step. Static for most actions; `sanitize` and
 *  `set_value` depend on the current values / loaded option lists. */
export function paramsFor(
  action: TransformationAction,
  subOrgOptions: FieldOption[] = [],
): ParamSpec[] {
  const meta = ACTION_CATALOGUE[action.type];
  if (!meta) return [];
  if (meta.params !== 'dynamic') return meta.params;
  const p = action.params || {};
  if (action.type === 'sanitize') {
    const base: ParamSpec[] = [
      {
        k: 'op',
        labelKey: 'operation',
        type: 'select',
        opts: ['keep', 'strip'],
        optLabelKeys: ['keep_only', 'strip_out'],
        struct: true,
      },
    ];
    if (p.op === 'strip') {
      base.push({ k: 'strip', labelKey: 'characters_to_strip', type: 'text', phKey: 'strip_chars_placeholder', wide: true });
    } else {
      base.push({
        k: 'keep',
        labelKey: 'keep_only',
        type: 'select',
        opts: ['alphanumeric', 'alpha', 'numeric', 'alphanumeric_space'],
        optLabelKeys: ['letters_and_digits', 'letters', 'digits', 'letters_digits_and_spaces'],
        wide: true,
      });
    }
    return base;
  }
  if (action.type === 'set_value') {
    return [
      {
        k: 'value',
        labelKey: 'sub_organisation',
        type: 'select',
        wide: true,
        opts: subOrgOptions.map((o) => o.value),
        optLabels: subOrgOptions.map((o) => o.label),
      },
    ];
  }
  // value_map renders its own pair editor; the flat specs below cover the rest.
  if (action.type === 'value_map') {
    return [
      { k: 'default', labelKey: 'when_no_match_label', type: 'text', phKey: 'keep_input', wide: true },
      { k: 'case_insensitive', labelKey: 'ignore_case_when_matching', type: 'toggle', wide: true },
    ];
  }
  return [];
}

// ---- Preview engine -----------------------------------------------------

function reEscape(s: string): string {
  return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** Apply ONE action to a value. Mirrors the backend evaluator closely enough
 *  for the live preview; a malformed pattern returns the input unchanged
 *  rather than throwing (the user is mid-typing). */
export function applyAction(input: unknown, action: TransformationAction): string {
  const s = input == null ? '' : String(input);
  const p = (action.params || {}) as Record<string, string | number | boolean | unknown>;
  const str = (k: string): string => (p[k] == null ? '' : String(p[k]));
  const num = (k: string): number => Number(p[k]) || 0;
  try {
    switch (action.type) {
      case 'case': {
        const mode = str('mode');
        if (mode === 'upper') return s.toUpperCase();
        if (mode === 'lower') return s.toLowerCase();
        if (mode === 'title') {
          return s.replace(/\w\S*/g, (w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase());
        }
        return s.charAt(0).toUpperCase() + s.slice(1);
      }
      case 'trim': {
        const side = str('side');
        const chars = str('chars');
        if (!chars) {
          if (side === 'left') return s.replace(/^\s+/, '');
          if (side === 'right') return s.replace(/\s+$/, '');
          return s.trim();
        }
        const cls = `[${reEscape(chars).replace(/\\(.)/g, '\\$1')}]+`;
        let out = s;
        if (side !== 'right') out = out.replace(new RegExp(`^${cls}`), '');
        if (side !== 'left') out = out.replace(new RegExp(`${cls}$`), '');
        return out;
      }
      case 'pad': {
        const len = num('length');
        const ch = str('char').charAt(0) || '0';
        return str('side') === 'right' ? s.padEnd(len, ch) : s.padStart(len, ch);
      }
      case 'truncate':
        return s.slice(0, Math.max(0, num('length')));
      case 'affix': {
        const mode = str('mode');
        const text = str('text');
        if (mode === 'add_prefix') return text + s;
        if (mode === 'add_suffix') return s + text;
        if (mode === 'strip_prefix') return text && s.startsWith(text) ? s.slice(text.length) : s;
        return text && s.endsWith(text) ? s.slice(0, -text.length) : s;
      }
      case 'sanitize': {
        if (str('op') === 'strip') {
          const strip = str('strip');
          return strip ? s.replace(new RegExp(`[${strip}]`, 'g'), '') : s;
        }
        const keep = str('keep');
        if (keep === 'alphanumeric') return s.replace(/[^A-Za-z0-9]/g, '');
        if (keep === 'alpha') return s.replace(/[^A-Za-z]/g, '');
        if (keep === 'numeric') return s.replace(/[^0-9]/g, '');
        return s.replace(/[^A-Za-z0-9 ]/g, '');
      }
      case 'substring': {
        const start = num('start');
        if (p.length !== '' && p.length != null) return s.slice(start, start + Number(p.length));
        if (p.end !== '' && p.end != null) return s.slice(start, Number(p.end));
        return s.slice(start);
      }
      case 'regex_replace': {
        const pattern = str('pattern');
        if (!pattern) return s;
        const all = num('count') === 0;
        return s.replace(new RegExp(pattern, all ? 'g' : ''), str('replacement'));
      }
      case 'regex_extract': {
        const pattern = str('pattern');
        if (!pattern) return s;
        const m = s.match(new RegExp(pattern));
        return m ? m[num('group')] || '' : '';
      }
      case 'value_map': {
        const ci = !!p.case_insensitive;
        const pairs = (p.pairs as [string, string][]) || [];
        const map: Record<string, string> = {};
        pairs.forEach((pair) => {
          if (pair && pair[0] !== '') map[ci ? String(pair[0]).toLowerCase() : String(pair[0])] = pair[1];
        });
        const key = ci ? s.toLowerCase() : s;
        if (Object.prototype.hasOwnProperty.call(map, key)) return map[key];
        const fallback = str('default');
        return fallback !== '' ? fallback : s;
      }
      case 'date_format': {
        const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s);
        if (!m) return s;
        const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        return str('pattern')
          .replace('%Y', m[1])
          .replace('%m', m[2])
          .replace('%d', m[3])
          .replace('%b', months[Number(m[2]) - 1] || m[2]);
      }
      case 'number_format': {
        const n = parseFloat(s.replace(',', '.'));
        if (Number.isNaN(n)) return s;
        const minRaw = p.min_decimal_places;
        const maxRaw = p.max_decimal_places;
        const mind = minRaw === '' || minRaw == null ? undefined : Number(minRaw);
        const maxd = maxRaw === '' || maxRaw == null ? undefined : Number(maxRaw);
        const locales: Record<string, string> = {
          de_DE: 'de-DE',
          en_US: 'en-US',
          en_GB: 'en-GB',
          fr_FR: 'fr-FR',
        };
        return n.toLocaleString(locales[str('locale')] || 'en-US', {
          minimumFractionDigits: mind,
          maximumFractionDigits: maxd != null ? maxd : mind != null ? Math.max(mind, 3) : 3,
        });
      }
      case 'set_value':
      case 'fix_value':
        // Both overwrite outright — whatever came in is discarded.
        return str('value');
      case 'clear':
        return '';
      default:
        return s;
    }
  } catch {
    // Half-typed regex / bad pattern — show the input untouched.
    return s;
  }
}

// ---- applies_when evaluation (preview only) ------------------------------
//
// A mirror of the backend's condition engine, good enough to answer one
// question in the live preview: "given these sample values, would this rule
// run at all?" Without it the preview shows the transformed result even for a
// document the rule would skip.

/** Every field referenced by a condition tree, in order, de-duplicated.
 *  Nested sub-groups are walked too. */
export function conditionFields(group: BuilderGroup): string[] {
  const out: string[] = [];
  const walk = (g: BuilderGroup) => {
    g.conditions.forEach((item) => {
      if (isBuilderGroup(item)) {
        walk(item);
      } else if (item.field && !out.includes(item.field)) {
        out.push(item.field);
      }
    });
  };
  walk(group);
  return out;
}

function asNumber(v: string): number {
  return Number(String(v).replace(',', '.'));
}

/** Evaluate one leaf condition against a resolved field value. */
export function evaluateCondition(
  c: BuilderCondition,
  resolve: (field: string) => string,
): boolean {
  const raw = resolve(c.field) ?? '';
  const fold = (s: string) => (c.case_insensitive ? s.toLowerCase() : s);
  const actual = fold(String(raw));
  const expected = fold(String(c.value ?? ''));

  let result: boolean;
  switch (c.op) {
    case 'empty':
      result = actual === '';
      break;
    case 'not_empty':
      result = actual !== '';
      break;
    case 'eq':
      result = actual === expected;
      break;
    case 'neq':
      result = actual !== expected;
      break;
    case 'in':
      result = expected
        .split(',')
        .map((v) => v.trim())
        .filter((v) => v !== '')
        .includes(actual.trim());
      break;
    case 'contains':
      result = actual.includes(expected);
      break;
    case 'starts_with':
      result = actual.startsWith(expected);
      break;
    case 'ends_with':
      result = actual.endsWith(expected);
      break;
    case 'gt':
      result = asNumber(actual) > asNumber(expected);
      break;
    case 'lt':
      result = asNumber(actual) < asNumber(expected);
      break;
    case 'gte':
      result = asNumber(actual) >= asNumber(expected);
      break;
    case 'lte':
      result = asNumber(actual) <= asNumber(expected);
      break;
    case 'matches':
      try {
        result = new RegExp(String(c.value ?? ''), c.case_insensitive ? 'i' : '').test(String(raw));
      } catch {
        // Half-typed pattern — treat as "no opinion" rather than throwing.
        result = false;
      }
      break;
    default:
      result = false;
  }
  return c.negate ? !result : result;
}

/** Evaluate a condition tree. An empty group means "no conditions", which the
 *  backend treats as always-applies — so it evaluates to true. */
export function evaluateGroup(
  group: BuilderGroup,
  resolve: (field: string) => string,
): boolean {
  // Leaves with no field chosen yet are ignored (they are also dropped on save).
  const items = group.conditions.filter((i) => isBuilderGroup(i) || i.field);
  if (!items.length) {
    return true;
  }
  const results = items.map((item) =>
    isBuilderGroup(item) ? evaluateGroup(item, resolve) : evaluateCondition(item, resolve),
  );
  return group.join === 'any' ? results.some(Boolean) : results.every(Boolean);
}

/** Run the whole pipeline, returning the value BEFORE the first step followed
 *  by the value after each step. Length is always actions.length + 1, so
 *  `chain[i]` is the input to step i and `chain[i + 1]` its output. */
export function chainValues(sampleInput: string, actions: TransformationAction[]): string[] {
  let v = sampleInput;
  const out = [v];
  actions.forEach((a) => {
    v = applyAction(v, a);
    out.push(v);
  });
  return out;
}

// ---- The whole editable form -------------------------------------------

export interface TransformationBuilderModel {
  rule_key: string;
  display_name: string;
  description: string;
  scope: TransformationRuleScope;
  /** Field / column / attribute the result is written to. */
  target_field: string;
  /** Namespaced field the pipeline reads from; '' = read the target itself. */
  source: string;
  table_name: string;
  priority: number;
  is_active: boolean;
  log_execution: boolean;
  /** Root of the applies_when tree; an empty group means "always". */
  group: BuilderGroup;
  /** UI-only: 'always' | 'cond' — mirrors whether the group has any rows. */
  when_mode: 'always' | 'cond';
  actions: TransformationAction[];
  /** UI-only: the value the live preview pipes through the actions. */
  sample_input: string;
}

export function emptyModel(
  scope: TransformationRuleScope = 'header',
): TransformationBuilderModel {
  return {
    rule_key: '',
    display_name: '',
    description: '',
    scope,
    target_field: '',
    source: '',
    table_name: '',
    priority: 0,
    is_active: true,
    log_execution: false,
    group: newGroup('all'),
    when_mode: 'always',
    actions: [newAction('trim')],
    sample_input: '',
  };
}

// ---- Assemble: builder form → API payload -------------------------------

// The builder keeps each step as { type, params: {...} } because that shape is
// convenient for the editor and the preview engine. The API instead wants the
// options FLAT alongside `type`, and three actions use a different encoding
// there than the editor does:
//
//   affix     — the chosen mode IS the key: { type, add_prefix: "INV-" }
//               (exactly one of add_prefix/add_suffix/strip_prefix/strip_suffix)
//   sanitize  — no `op`; presence of `keep` or `strip` selects the branch
//   value_map — a `mappings` OBJECT { from: to }, not a `pairs` array
//
// So the flattening lives here, at the API boundary only.

/** Options that are meaningful only inside the editor and never sent. */
const EDITOR_ONLY_PARAMS: Record<string, string[]> = {
  affix: ['mode', 'text'],
  // The editor keeps BOTH branches so switching op doesn't lose what was typed;
  // only the selected one may be emitted (the backend rejects the other).
  sanitize: ['op', 'keep', 'strip'],
  value_map: ['pairs'],
};

// Every numeric param across the catalogue, derived once. A number left blank
// is omitted rather than sent as '' so the backend applies its own default —
// deriving the set means adding a numeric param to any action is enough.
const NUMBER_PARAM_KEYS = new Set(
  Object.values(ACTION_CATALOGUE)
    .flatMap((meta) => (meta.params === 'dynamic' ? [] : meta.params))
    .filter((spec) => spec.type === 'number')
    .map((spec) => spec.k),
);

function isBlankOptional(key: string, value: unknown): boolean {
  return value === '' && NUMBER_PARAM_KEYS.has(key);
}

/** One builder step → the flat action object the API expects. */
export function actionToApi(action: TransformationAction): TransformationAction {
  const p = (action.params || {}) as Record<string, unknown>;
  const out: TransformationAction = { type: action.type };
  const skip = EDITOR_ONLY_PARAMS[action.type] || [];

  Object.keys(p).forEach((k) => {
    if (skip.includes(k) || isBlankOptional(k, p[k])) return;
    out[k] = p[k];
  });

  if (action.type === 'affix') {
    // The mode selects which key carries the text.
    const mode = String(p.mode || 'add_prefix');
    out[mode] = String(p.text ?? '');
  } else if (action.type === 'sanitize') {
    // Emit only the branch the op selected; the other must not be present.
    if (p.op === 'strip') out.strip = p.strip ?? '';
    else out.keep = p.keep ?? 'alphanumeric';
  } else if (action.type === 'value_map') {
    // pairs [[from, to]] → mappings { from: to }, dropping half-filled rows.
    const mappings: Record<string, string> = {};
    ((p.pairs as [string, string][]) || []).forEach((pair) => {
      if (pair && pair[0] !== '') mappings[String(pair[0])] = String(pair[1] ?? '');
    });
    out.mappings = mappings;
  } else if (action.type === 'substring') {
    // The backend takes start + EITHER length OR end; length wins when both are
    // filled in (the label reads "Length (or use End)").
    if (out.length !== undefined && out.length !== '') delete out.end;
  }
  return out;
}

/** A flat API action → the builder's { type, params } shape, merged over the
 *  catalogue defaults so every input still has something to bind to. */
export function actionFromApi(raw: TransformationAction): TransformationAction {
  const type = String(raw.type || 'trim');
  // Read the branch selectors off the RAW payload: the defaults merged in below
  // carry both sanitize branches, so testing the merged object would always
  // report whichever default happens to exist.
  const rawNested = (raw.params as Record<string, unknown>) || {};
  const rawHas = (k: string) => raw[k] !== undefined || rawNested[k] !== undefined;
  const params: Record<string, unknown> = { ...defaultParams(type) };

  Object.keys(raw).forEach((k) => {
    if (k === 'type' || k === 'params') return;
    params[k] = raw[k];
  });
  // Tolerate a nested `params` too, so a rule saved by an older build (or by
  // another client) still opens in the editor.
  Object.assign(params, (raw.params as Record<string, unknown>) || {});

  if (type === 'affix') {
    const MODES = ['add_prefix', 'add_suffix', 'strip_prefix', 'strip_suffix'];
    const mode = MODES.find((m) => rawHas(m));
    if (mode) {
      params.mode = mode;
      params.text = params[mode];
      MODES.forEach((m) => delete params[m]);
    }
  } else if (type === 'sanitize') {
    // Whichever key the payload carries selects the branch; seed the other from
    // its default so switching op in the editor still has something to show.
    params.op = rawHas('strip') && !rawHas('keep') ? 'strip' : 'keep';
  } else if (type === 'value_map') {
    const mappings = params.mappings as Record<string, string> | undefined;
    if (mappings) {
      const pairs = Object.entries(mappings).map(([from, to]) => [from, String(to ?? '')]);
      params.pairs = pairs.length ? pairs : [['', '']];
      delete params.mappings;
    }
  }
  return { type, params };
}

export function assembleApiCore(
  m: TransformationBuilderModel,
): UpdateTransformationRulePayload {
  const core: UpdateTransformationRulePayload = {
    display_name: m.display_name,
    description: m.description || null,
    target_field: m.target_field,
    actions: m.actions.map(actionToApi),
    priority: Number(m.priority) || 0,
    is_active: m.is_active,
    log_execution: m.log_execution,
  };
  // '' means "read the target itself" — send null so the backend transforms
  // in place rather than looking up a field named ''.
  core.source = m.source || null;
  // Send the table for column-scoped rules so it round-trips (a PUT that omits
  // it could drop the rule's table server-side).
  if (m.scope === 'column' && m.table_name) {
    core.table_name = m.table_name;
  }
  // Only attach applies_when when the user actually built conditions — an
  // empty group serializes to { all: [] }, which we omit rather than send.
  if (m.when_mode === 'cond') {
    const appliesWhen = buildAppliesWhenFromGroup(m.group);
    if (!isAppliesWhenEmpty(appliesWhen)) {
      core.applies_when = appliesWhen;
    }
  }
  return core;
}

// ---- Parse: API rule → builder form (edit mode) -------------------------

export function fromApiRule(rule: TransformationRule): TransformationBuilderModel {
  const m = emptyModel(rule.scope);
  m.rule_key = rule.rule_key || '';
  m.display_name = rule.display_name || '';
  m.description = rule.description || '';
  m.target_field = rule.target_field || '';
  m.source = rule.source || '';
  m.table_name = rule.table_name || '';
  m.priority = rule.priority || 0;
  m.is_active = !!rule.is_active;
  m.log_execution = !!rule.log_execution;

  const aw = rule.applies_when || {};
  const join: 'all' | 'any' = Array.isArray(aw.any) ? 'any' : 'all';
  m.group = groupFromAppliesWhen(aw, join);
  m.when_mode = m.group.conditions.length > 0 ? 'cond' : 'always';

  // A rule always has at least one action server-side, but be defensive: an
  // empty pipeline would leave the builder with nothing to edit.
  const actions = Array.isArray(rule.actions) ? rule.actions : [];
  m.actions = actions.length
    ? actions.map(actionFromApi)
    : [newAction(rule.scope === 'document' ? 'set_value' : 'trim')];
  return m;
}

// ---- Plain-English summary ---------------------------------------------

/** Strip the `header.` / `row.` / `doc.` namespace off a field reference. */
export function shortFieldName(ref: string): string {
  if (!ref) return '';
  const i = ref.indexOf('.');
  return i < 0 ? ref : ref.slice(i + 1);
}


/** Verb phrase for one step, e.g. "pad to 10 with “0”". `t` is the caller's
 *  translate function; `labelFor` resolves a stored sub-org id to its name. */
export function actionPhrase(
  action: TransformationAction,
  t: (key: string, params?: Record<string, unknown>) => string,
  labelFor: (value: string) => string = (v) => v,
): string {
  const p = (action.params || {}) as Record<string, unknown>;
  const str = (k: string): string => (p[k] == null ? '' : String(p[k]));
  switch (action.type) {
    case 'case':
      return t(
        {
          upper: 'phrase_make_it_uppercase',
          lower: 'phrase_make_it_lowercase',
          title: 'phrase_make_it_title_case',
          capitalize: 'phrase_capitalise_first_letter',
        }[str('mode')] || 'phrase_make_it_uppercase',
      );
    case 'trim':
      return t('phrase_trim', {
        what: str('chars') ? `“${str('chars')}”` : t('whitespace'),
      });
    case 'pad':
      return t('phrase_pad', { length: str('length'), char: str('char') });
    case 'truncate':
      return t('phrase_truncate', { length: str('length') });
    case 'affix':
      return t(
        {
          add_prefix: 'phrase_add_prefix',
          add_suffix: 'phrase_add_suffix',
          strip_prefix: 'phrase_strip_prefix',
          strip_suffix: 'phrase_strip_suffix',
        }[str('mode')] || 'phrase_add_prefix',
        { text: str('text') },
      );
    case 'sanitize':
      if (str('op') === 'strip') return t('phrase_strip_chars', { chars: str('strip') });
      return t('phrase_keep', {
        what: t(
          {
            alphanumeric: 'letters_and_digits',
            alpha: 'letters',
            numeric: 'digits',
            alphanumeric_space: 'letters_digits_and_spaces',
          }[str('keep')] || 'letters_and_digits',
        ).toLowerCase(),
      });
    case 'substring': {
      const start = Number(p.start) || 0;
      const end =
        p.length !== '' && p.length != null
          ? String(start + Number(p.length))
          : p.end !== '' && p.end != null
            ? String(p.end)
            : t('phrase_end');
      return t('phrase_take_characters', { start: String(start), end });
    }
    case 'regex_replace':
      return t('phrase_replace_pattern', {
        pattern: str('pattern') ? `/${str('pattern')}/` : t('phrase_a_pattern'),
        replacement: str('replacement'),
      });
    case 'regex_extract':
      return t('phrase_extract_pattern', {
        pattern: str('pattern') ? `/${str('pattern')}/` : t('phrase_a_pattern'),
      });
    case 'value_map': {
      const count = ((p.pairs as [string, string][]) || []).filter((x) => x && x[0] !== '').length;
      return t('phrase_map_values', { count: String(count) });
    }
    case 'date_format':
      return t('phrase_format_date', { pattern: str('pattern') });
    case 'number_format':
      return t('phrase_format_number', { locale: str('locale') });
    case 'set_value':
      // The routing sentence already reads "route this document to …".
      return `“${labelFor(str('value'))}”`;
    case 'fix_value':
      // Joins a list of imperatives ("trim …, then …"), so it needs the verb.
      return t('phrase_fix_value', { value: str('value') });
    case 'clear':
      return t('phrase_clear');
    default:
      return action.type;
  }
}

/** A `{ text, code }` token stream for the rule summary. The caller renders
 *  `code` tokens as field chips — building the sentence as data (rather than an
 *  HTML string) keeps it escape-safe and translatable. */
export interface SentenceToken {
  text: string;
  /** 'field' → a field-name chip, 'cond' → a condition chip, undefined → prose. */
  kind?: 'field' | 'cond' | 'strong';
}

interface RuleSentenceInput {
  scope: TransformationRuleScope;
  target_field: string;
  source: string;
  actions: TransformationAction[];
  /** Rendered condition phrases; empty means "always". */
  conditions: string[];
  /** 'all' | 'any' — how the conditions join. */
  join: 'all' | 'any';
}

/** Build the plain-English sentence shown in the list and the builder banner,
 *  e.g. "On every INVOICE, take supplier_name, trim whitespace, then make it
 *  UPPERCASE, and save it back." */
export function ruleSentence(
  r: RuleSentenceInput,
  docType: string,
  t: (key: string, params?: Record<string, unknown>) => string,
  labelFor: (value: string) => string = (v) => v,
): SentenceToken[] {
  const out: SentenceToken[] = [];
  if (!r.conditions.length) {
    out.push({ text: t('on_every_doc_type', { docType }) });
  } else {
    out.push({ text: t('when') });
    const joiner = r.join === 'any' ? t('join_or') : t('join_and');
    r.conditions.forEach((c, i) => {
      if (i > 0) out.push({ text: ` ${joiner} ` });
      out.push({ text: c, kind: 'cond' });
    });
  }

  const steps = r.actions.map((a) => actionPhrase(a, t, labelFor)).join(t('join_then'));

  if (r.scope === 'document') {
    out.push({ text: `, ${t('sentence_route_this_document_to')} ` });
    if (r.source) {
      out.push({ text: t('sentence_the_mapped_sub_organisation'), kind: 'strong' });
      out.push({ text: ` ${t('sentence_by_looking_up')} ` });
      out.push({ text: shortFieldName(r.source), kind: 'field' });
    } else {
      out.push({
        text: r.actions.length ? actionPhrase(r.actions[0], t, labelFor) : '—',
        kind: 'strong',
      });
    }
    out.push({ text: '.' });
    return out;
  }

  // With no steps there is no clause to splice between the target and "and save
  // it back", so say what's missing instead.
  if (!r.actions.length) {
    out.push({ text: `, ${t('sentence_take')} ` });
    out.push({ text: r.source ? shortFieldName(r.source) : r.target_field || '—', kind: 'field' });
    out.push({ text: ` — ${t('sentence_no_steps_yet')}.` });
    return out;
  }

  if (r.source) {
    out.push({ text: `, ${t('sentence_read')} ` });
    out.push({ text: shortFieldName(r.source), kind: 'field' });
    out.push({ text: `, ${steps}, ${t('sentence_and_write_it_to')} ` });
    out.push({ text: r.target_field || '—', kind: 'field' });
    out.push({ text: '.' });
    return out;
  }

  out.push({ text: `, ${t('sentence_take')} ` });
  out.push({ text: r.target_field || '—', kind: 'field' });
  out.push({ text: `, ${steps}, ${t('sentence_and_save_it_back')}.` });
  return out;
}

/** Plain-text flattening of the sentence — used for search and tooltips. */
export function sentenceText(tokens: SentenceToken[]): string {
  return tokens.map((tk) => tk.text).join('');
}
